// libvsql.c is libvsql, the SQL/CLI (ISO/IEC 9075-3) shared library (see libvsql.h), as C generated by V.
//
// V can generate one C file for every OS and architecture (-os cross), but
// that C has no garbage collector (https://github.com/vlang/v/issues/31421), so
// the C is generated on each OS and architecture instead. Once that's fixed,
// this file will be replaced by the cross platform C.
#if defined(__x86_64__) || defined(_M_X64)
#define VSQL_AMD64
#elif defined(__aarch64__) || defined(_M_ARM64)
#define VSQL_ARM64
#endif

#if defined(_WIN32) && defined(VSQL_AMD64)
#include "libvsql_windows_amd64.c"
#elif defined(_WIN32) && defined(VSQL_ARM64)
#include "libvsql_windows_arm64.c"
#elif defined(__APPLE__) && defined(VSQL_AMD64)
#include "libvsql_macos_amd64.c"
#elif defined(__APPLE__) && defined(VSQL_ARM64)
#include "libvsql_macos_arm64.c"
#elif defined(__linux__) && defined(VSQL_AMD64)
#include "libvsql_linux_amd64.c"
#elif defined(__linux__) && defined(VSQL_ARM64)
#include "libvsql_linux_arm64.c"
#else
#error "There is no generated C for this OS and architecture."
#endif
